      arrow(ctx, xs.getPixelForValue(XMAX), y0, 0, 9, '#000');
      arrow(ctx, xs.getPixelForValue(XMIN), y0, Math.PI, 9, '#000');
      arrow(ctx, x0, ys.getPixelForValue(YMAX), -Math.PI / 2, 9, '#000');
      arrow(ctx, x0, ys.getPixelForValue(YMIN), Math.PI / 2, 9, '#000');
      ctx.fillStyle = '#000'; ctx.font = 'italic 13px sans-serif';
      ctx.fillText('x', xs.getPixelForValue(XMAX) + 4, y0 + 4);
      ctx.fillText('y', x0 + 6, ys.getPixelForValue(YMAX) - 2);

      // line-end arrowheads + Roman numeral labels
      function drawEnds(ends, color, label, hi) {
        if (!ends) return;
        var p1 = { x: xs.getPixelForValue(ends[0].x), y: ys.getPixelForValue(ends[0].y) };
        var p2 = { x: xs.getPixelForValue(ends[1].x), y: ys.getPixelForValue(ends[1].y) };
        var ang = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        arrow(ctx, p2.x, p2.y, ang, 8, color);
        arrow(ctx, p1.x, p1.y, ang + Math.PI, 8, color);
        var lp = hi ? p2 : p1;
        ctx.fillStyle = color; ctx.font = 'bold 13px sans-serif';
        ctx.attr = null;
