          var id = chart.data.datasets[els[0].datasetIndex]._lineId;
          if (id !== 'cand' && id !== 'dot') { state.selected = (state.selected === id) ? null : id; chart.update(); }
        }
      },
      onHover: function (e, els) { e.native.target.style.cursor = els.length ? 'pointer' : 'default'; }
    },
    plugins: [overlayPlugin]
  });
  window.__markRendered();

  function refreshCandidate() {
    var ce = clipLine(state.m, state.b) || [{ x: 0, y: state.b }, { x: 0, y: state.b }];
    chart.data.datasets[4].data = ce;
    chart.data.datasets[5].data = [{ x: 0, y: state.b }];
    document.getElementById('eqReadout').textContent = 'y = ' + state.m + '·x + ' + state.b;
    chart.update();
  }

  window.update_slopeSlider = function (v) { state.m = v; refreshCandidate(); };
  window.update_interceptSlider = function (v) { state.b = v; refreshCandidate(); };

  // ---- demo step player ----
  var steps = [
    { t: 'Four lines, two parameters', n: 'Four lines share the same coordinate plane. Lines I, II, and IV all cross the y-axis at 3 but fan out at different angles; line III crosses at −3. The two numbers that distinguish them are slope and y-intercept.', m: 1, b: 0, sel: null },
    { t: 'Read the slope visually', n: 'Click line IV (dark blue). A right-triangle overlay appears showing a run of 1 and a rise of −2, confirming slope = −2. Click line I (orange) to see its much steeper rise-over-run of 5/1.', m: 1, b: 0, sel: 'IV' },
    { t: 'Match slope, then intercept', n: 'Set the slope slider to 2 — the candidate line now has the same angle as line III but sits too high. Drag the y-intercept slider down to −3 and the candidate line lands exactly on line III, confirming y = 2x − 3.', m: 2, b: -3, sel: null },
    { t: 'Same intercept, different slopes', n: 'Set b = 3 and sweep the slope slider from −2 through 0.5 to 5. The candidate line pivots through lines IV, II, and I in sequence — all three share the y-intercept 3 but are distinguished entirely by slope.', m: 0.5, b: 3, sel: null }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    state.m = s.m; state.b = s.b; state.selected = s.sel;
    document.getElementById('slopeSliderInput').value = s.m;
    document.getElementById('slopeSliderVal').value = s.m;
    document.getElementById('interceptSliderInput').value = s.b;
    document.getElementById('interceptSliderVal').value = s.b;
    document.getElementById('eqReadout').textContent = 'y = ' + s.m + '·x + ' + s.b;
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + s.t;
    chart.update();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  applyStep(0);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: A line's equation y = mx + b is fully determined by its slope m (steepness and direction) and y-intercept b (where it crosses the vertical axis), and these two parameters can be read directly from the graph.
KEY INSIGHT (what students should walk away understanding): Every line on the plane is uniquely identified by just two numbers — where it crosses the y-axis (b) and how steeply it rises or falls (m) — and both can be read directly from the graph.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
