(function () {
  var XMIN = -7, XMAX = 7, YMIN = -5, YMAX = 5;
  var ORANGE = '#E8611A', LBLUE = '#5BA3D9', TEAL = '#1A9E8F', NAVY = '#1B3A6B', MAG = '#C0399A';

  function clipLine(m, b) {
    var x1 = -100, y1 = m * x1 + b, x2 = 100, y2 = m * x2 + b;
    var LEFT = 1, RIGHT = 2, BOTTOM = 4, TOP = 8;
    function code(x, y) {
      var c = 0;
      if (x < XMIN) c |= LEFT; else if (x > XMAX) c |= RIGHT;
      if (y < YMIN) c |= BOTTOM; else if (y > YMAX) c |= TOP;
      return c;
    }
    var c1 = code(x1, y1), c2 = code(x2, y2);
    for (var i = 0; i < 20; i++) {
      if (!(c1 | c2)) break;
      if (c1 & c2) return null;
      var c = c1 ? c1 : c2, x, y;
      if (c & TOP) { x = x1 + (x2 - x1) * (YMAX - y1) / (y2 - y1); y = YMAX; }
      else if (c & BOTTOM) { x = x1 + (x2 - x1) * (YMIN - y1) / (y2 - y1); y = YMIN; }
      else if (c & RIGHT) { y = y1 + (y2 - y1) * (XMAX - x1) / (x2 - x1); x = XMAX; }
      else { y = y1 + (y2 - y1) * (XMIN - x1) / (x2 - x1); x = XMIN; }
      if (c === c1) { x1 = x; y1 = y; c1 = code(x1, y1); } else { x2 = x; y2 = y; c2 = code(x2, y2); }
    }
    return [{ x: x1, y: y1 }, { x: x2, y: y2 }];
  }

  // All four labels sit at the right-hand (high-x) clipped end: for I/II/III that is
  // the upper-right terminus, and for IV (negative slope) it is the lower-right terminus,
  // exactly matching the source placement.
  var LINES = [
    { id: 'I',   color: ORANGE, m: 5,   b: 3,  label: 'I',   base: { x: -1, run: 1 } },
    { id: 'II',  color: LBLUE,  m: 0.5, b: 3,  label: 'II',  base: { x: 0,  run: 2 } },
    { id: 'III', color: TEAL,   m: 2,   b: -3, label: 'III', base: { x: 1,  run: 1 } },
    { id: 'IV',  color: NAVY,   m: -2,  b: 3,  label: 'IV',  base: { x: 1,  run: 1 } }
  ];
  LINES.forEach(function (L) { L.ends = clipLine(L.m, L.b); });

  var state = { m: 1, b: 0, selected: null, candVisible: false };

  function arrow(ctx, x, y, ang, size, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-size, -size * 0.5); ctx.lineTo(-size, size * 0.5);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill(); ctx.restore();
  }

  var overlayPlugin = {
    id: 'overlay',
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, xs = chart.scales.x, ys = chart.scales.y;
      var x0 = xs.getPixelForValue(0), y0 = ys.getPixelForValue(0);
      ctx.save();

      // bold black central axes with arrowheads
      ctx.strokeStyle = '#000'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(xs.getPixelForValue(XMIN), y0); ctx.lineTo(xs.getPixelForValue(XMAX), y0); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x0, ys.getPixelForValue(YMIN)); ctx.lineTo(x0, ys.getPixelForValue(YMAX)); ctx.stroke();
      arrow(ctx, xs.getPixelForValue(XMAX), y0, 0, 9, '#000');
      arrow(ctx, xs.getPixelForValue(XMIN), y0, Math.PI, 9, '#000');
      arrow(ctx, x0, ys.getPixelForValue(YMAX), -Math.PI / 2, 9, '#000');
      arrow(ctx, x0, ys.getPixelForValue(YMIN), Math.PI / 2, 9, '#000');
      ctx.fillStyle = '#000'; ctx.font = 'italic 13px sans-serif';
      ctx.fillText('x', xs.getPixelForValue(XMAX) + 4, y0 + 4);
      ctx.fillText('y', x0 + 6, ys.getPixelForValue(YMAX) - 2);

      // numeric tick labels hugging the central axes (not the canvas border)
      ctx.fillStyle = '#333'; ctx.font = '11px sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      for (var xi = XMIN; xi <= XMAX; xi++) {
        if (xi === 0) continue;
        ctx.fillText(String(xi), xs.getPixelForValue(xi), y0 + 5);
      }
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      for (var yi = YMIN; yi <= YMAX; yi++) {
        if (yi === 0) continue;
        ctx.fillText(String(yi), x0 - 6, ys.getPixelForValue(yi));
      }
      ctx.textAlign = 'right'; ctx.textBaseline = 'top';
      ctx.fillText('0', x0 - 6, y0 + 5);

      // line-end arrowheads + Roman numeral labels (label at high-x end)
      LINES.forEach(function (L) {
        if (!L.ends) return;
        var p1 = { x: xs.getPixelForValue(L.ends[0].x), y: ys.getPixelForValue(L.ends[0].y) };
        var p2 = { x: xs.getPixelForValue(L.ends[1].x), y: ys.getPixelForValue(L.ends[1].y) };
        var ang = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        arrow(ctx, p2.x, p2.y, ang, 8, L.color);
        arrow(ctx, p1.x, p1.y, ang + Math.PI, 8, L.color);
        ctx.save();
        ctx.shadowColor = '#fff'; ctx.shadowBlur = 3;
        ctx.fillStyle = L.color; ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
        ctx.fillText(L.label, p2.x + 6, p2.y - 4);
        ctx.restore();
      });

      // candidate line + intercept dot (only when revealed)
      if (state.candVisible) {
        var ce = clipLine(state.m, state.b);
        if (ce) {
          var q1 = { x: xs.getPixelForValue(ce[0].x), y: ys.getPixelForValue(ce[0].y) };
          var q2 = { x: xs.getPixelForValue(ce[1].x), y: ys.getPixelForValue(ce[1].y) };
          var a2 = Math.atan2(q2.y - q1.y, q2.x - q1.x);
          arrow(ctx, q2.x, q2.y, a2, 7, MAG); arrow(ctx, q1.x, q1.y, a2 + Math.PI, 7, MAG);
        }
        var dy = ys.getPixelForValue(state.b);
        ctx.beginPath(); ctx.arc(x0, dy, 5, 0, Math.PI * 2);
        ctx.fillStyle = MAG; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = '#fff'; ctx.stroke();
      }

      // rise-over-run triangle for the selected line
      if (state.selected) {
        var L = LINES.filter(function (d) { return d.id === state.selected; })[0];
        if (L) {
          var bx = L.base.x, run = L.base.run, rise = L.m * run, by = L.m * bx + L.b;
          var ax = xs.getPixelForValue(bx), ay = ys.getPixelForValue(by);
          var cx = xs.getPixelForValue(bx + run), cy = ay;
          var tx = cx, ty = ys.getPixelForValue(by + rise);
          ctx.lineWidth = 2.5;
          ctx.strokeStyle = L.color; ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(cx, cy); ctx.stroke();
          ctx.strokeStyle = '#888'; ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(tx, ty); ctx.stroke();
          var s = 8, sx = (ax < cx ? -1 : 1), sy = (ty < cy ? 1 : -1);
          ctx.strokeStyle = '#333'; ctx.lineWidth = 1.5;
          ctx.beginPath(); ctx.moveTo(cx + sx * s, cy); ctx.lineTo(cx + sx * s, cy + sy * s); ctx.lineTo(cx, cy + sy * s); ctx.stroke();
          ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
          ctx.fillStyle = L.color; ctx.font = '11px sans-serif';
          ctx.fillText('run=' + run, (ax + cx) / 2 - 16, ay + 14);
          ctx.fillStyle = '#555';
          ctx.fillText('rise=' + rise, cx + 6, (cy + ty) / 2);
        }
      }
      ctx.restore();
    }
  };

  function lineDataset(L) {
    return {
      label: 'Line ' + L.id, data: L.ends, borderColor: L.color, borderWidth: 2.5,
      pointRadius: 0, pointHitRadius: 12, tension: 0, _lineId: L.id
    };
  }

  var candEnds = clipLine(state.m, state.b) || [{ x: 0, y: 0 }, { x: 0, y: 0 }];
  var chart = new Chart(document.getElementById('container').appendChild(Object.assign(document.createElement('canvas'), { style: 'width:100%;height:100%;display:block' })), {
    type: 'line',
    data: {
      datasets: LINES.map(lineDataset).concat([
        { label: 'candidate', data: candEnds, borderColor: MAG, borderWidth: 2.5, borderDash: [7, 5], pointRadius: 0, pointHitRadius: 12, tension: 0, _lineId: 'cand', hidden: true },
        { label: 'y-int', data: [{ x: 0, y: state.b }], showLine: false, pointRadius: 0, pointHitRadius: 0, _lineId: 'dot', hidden: true }
      ])
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: { duration: 250 },
      parsing: false, normalized: true,
      scales: {
        x: { type: 'linear', min: XMIN, max: XMAX, ticks: { display: false, stepSize: 1 }, grid: { color: '#dcdcdc' }, border: { display: false } },
        y: { type: 'linear', min: YMIN, max: YMAX, ticks: { display: false, stepSize: 1 }, grid: { color: '#dcdcdc' }, border: { display: false } }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: function (c) {
              var id = c.dataset._lineId;
              if (id === 'dot') return 'y-intercept (0, ' + state.b + ')';
              if (id === 'cand') return 'candidate: y = ' + state.m + 'x + ' + state.b;
              var L = LINES.filter(function (d) { return d.id === id; })[0];
              return 'Line ' + L.id + ': y = ' + L.m + 'x + ' + L.b;
            }
          }
        }
      },
      onClick: function (e, els) {
        if (els.length) {
          var id = chart.data.datasets[els[0].datasetIndex]._lineId;
          if (id !== 'cand' && id !== 'dot') { state.selected = (state.selected === id) ? null : id; chart.update(); }
        }
      },
      onHover: function (e, els) {
        var hit = els.filter(function (el) { var id = chart.data.datasets[el.datasetIndex]._lineId; return id !== 'cand' && id !== 'dot'; });
        e.native.target.style.cursor = hit.length ? 'pointer' : 'default';
      }
    },
    plugins: [overlayPlugin]
  });
  window.__markRendered();

  function refreshCandidate() {
    var ce = clipLine(state.m, state.b) || [{ x: 0, y: state.b }, { x: 0, y: state.b }];
    chart.data.datasets[4].data = ce;
    chart.data.datasets[4].hidden = !state.candVisible;
    chart.data.datasets[5].data = [{ x: 0, y: state.b }];
    chart.data.datasets[5].hidden = !state.candVisible;
    var ro = document.getElementById('eqReadout');
    if (state.candVisible) {
      ro.style.color = MAG;
      ro.textContent = 'y = ' + state.m + '·x + ' + state.b;
    } else {
      ro.style.color = '#999';
      ro.textContent = 'move a slider to draw a candidate line';
    }
    chart.update();
  }

  window.update_slopeSlider = function (v) { state.m = v; state.candVisible = true; refreshCandidate(); };
  window.update_interceptSlider = function (v) { state.b = v; state.candVisible = true; refreshCandidate(); };

  var steps = [
    { t: 'Four lines, two parameters', n: 'Four lines share the same coordinate plane. Lines I, II, and IV all cross the y-axis at 3 but fan out at different angles; line III crosses at −3. The two numbers that distinguish them are slope and y-intercept.', m: 1, b: 0, sel: null, cand: false },
    { t: 'Read the slope visually', n: 'Click line IV (dark blue). A right-triangle overlay appears showing a run of 1 and a rise of −2, confirming slope = −2. Click line I (orange) to see its much steeper rise-over-run of 5/1.', m: 1, b: 0, sel: 'IV', cand: false },
    { t: 'Match slope, then intercept', n: 'Set the slope slider to 2 — the candidate line now has the same angle as line III but sits too high. Drag the y-intercept slider down to −3 and the candidate line lands exactly on line III, confirming y = 2x − 3.', m: 2, b: -3, sel: null, cand: true },
    { t: 'Same intercept, different slopes', n: 'Set b = 3 and sweep the slope slider from −2 through 0.5 to 5. The candidate line pivots through lines IV, II, and I in sequence — all three share the y-intercept 3 but are distinguished entirely by slope.', m: 0.5, b: 3, sel: null, cand: true }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    state.m = s.m; state.b = s.b; state.selected = s.sel; state.candVisible = s.cand;
    document.getElementById('slopeSliderInput').value = s.m;
    document.getElementById('slopeSliderVal').value = s.m;
    document.getElementById('interceptSliderInput').value = s.b;
    document.getElementById('interceptSliderVal').value = s.b;
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + s.t;
    refreshCandidate();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  applyStep(0);
})();
