  window.update_interceptSlider = function (v) { state.b = v; state.candVisible = true; refreshCandidate(); };

  var steps = [
    { t: 'Four lines, two parameters', n: 'Four lines share the same coordinate plane. Lines I, II, and IV all cross the y-axis at 3 but fan out at different angles; line III crosses at −3. The two numbers that distinguish them are slope and y-intercept.', m: 1, b: 0, sel: null, cand: false },
    { t: 'Read the slope visually', n: 'Click line IV (dark blue). A right-triangle overlay appears showing a run of 1 and a rise of −2, confirming slope = −2. Click line I (orange) to see its much steeper rise-over-run of 5/1.', m: 1, b: 0, sel: 'IV', cand: false },
    { t: 'Match slope, then intercept', n: 'Set the slope slider to 2 — the candidate line now has the same angle as line III but sits too high. Drag the y-intercept slider down to −3 and the candidate line lands exactly on line III, confirming y = 2x − 3.', m: 2, b: -3, sel: null, cand: true },
